import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"58、【兑】 兑下兑上","description":"周易集注 - 58、【兑】 兑下兑上","frontmatter":{"title":"58、【兑】 兑下兑上","description":"周易集注 - 58、【兑】 兑下兑上"},"headers":[],"relativePath":"zh/classics/jizhu/062.md","filePath":"zh/classics/jizhu/062.md"}'),l={name:"zh/classics/jizhu/062.md"};function h(t,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_58、【兑】-兑下兑上" tabindex="-1">58、【兑】 兑下兑上 <a class="header-anchor" href="#_58、【兑】-兑下兑上" aria-label="Permalink to “58、【兑】 兑下兑上”">​</a></h1><p>兑悦也，一阴进于二阳之上，喜悦之见于外也，故为兑。《序卦》：巽者入也，入而后悦之，故受之以兑，所以次巽。</p><p>亨者，因卦之所有而与之也。贞者，因卦之不足而戒之也。说则亨矣。但阴阳相说，易流于不正，故戒以利贞。</p><p>《彖》曰：兑，说也，刚中而柔外，说以利贞，是以顺乎天而应乎人。说以先民，民忘其劳;说以犯难，民忘其死，说之大，民劝矣哉!先西荐反，难乃旦反</p><p>释卦名，又以卦体释卦辞，而极赞之。兑，说也，与咸感也。同感去其心，说去其言，故咸则无心之感，兑则无言之说也。刚中指二五，柔外指三上。阳刚居中，中心诚实之象。柔爻在外，接物和柔之象。外虽柔说，中实刚介，是之谓说而贞，故利贞。易有天道焉，顺天者上兑也。有人道焉，应人者下兑也。揆之天理而顺，故顺天。即之人心而安，故应人。天理人心，正而已矣。若说之不以正，则不能顺应矣。民忘其劳，如禹之随山濬川，周宣之城朔方是也。民忘其死，如汤之东征西怨，岳飞蔡州朱仙之战是也。</p><p>说本有亨，而又利贞者，盖卦体刚中，则所存者诚，固无不亨。柔外，恐说之不正，故必正而后利也。说得其正，是以顺天应人。以之先民，民忘其劳，以之犯难，民忘其死。夫好逸恶死，人情之常，今忘劳忘死，非人情也。而忘之者以说，而不自知其劳且死也。曷为而说也，知圣人劳我以逸我，死我以生我也，是以说而自劝也。夫劝民与民自劝，相去远矣，是以圣人大之曰“说之大，民劝矣哉”，此正之所以利也。</p><h3 id="《象》曰-丽泽兑-君子以朋友讲习。" tabindex="-1">《象》曰：丽泽兑，君子以朋友讲习。 <a class="header-anchor" href="#《象》曰-丽泽兑-君子以朋友讲习。" aria-label="Permalink to “《象》曰：丽泽兑，君子以朋友讲习。”">​</a></h3><p>丽者附丽也，两泽相丽，交相浸润，互有滋益。水就湿，各以类而相从。朋友之道，不出乎此。习者，鸟数飞也。其字从羽。《月令》“鹰乃学习”，借鸟以明学，盖习行所传之业，为之习熟不已也。讲者资友讲之，以究其理。习者我自习之，以践其事。朋友之间，从容论说，以讲之于先，我又切实体验，以习之于后，则心与理相涵，而所知者益精。身与事相安，而所能者益固，欲罢不能，而真说在我矣。</p><p>初九，和兑，吉。</p><p>和与中庸，发而皆中节谓之和。和字，同谓其所悦者，无乖戾之私，皆情性之正，道义之公也。吉者，无恶无射，家邦必达之意。盖悦能和，即顺天应人，岂不吉。</p><p>初九以阳爻居说体，而处最下，又无应与之系，说得其正者也。故其象占如此。</p><h3 id="《象》曰-和兑之吉-行未疑也。" tabindex="-1">《象》曰：和兑之吉，行未疑也。 <a class="header-anchor" href="#《象》曰-和兑之吉-行未疑也。" aria-label="Permalink to “《象》曰：和兑之吉，行未疑也。”">​</a></h3><p>本卦说体，不当阴阳相比。二比三，三比四，五比六，阴阳相比，则不能无疑，故夬卦上说体。《小象》曰中未光也，萃卦曰志未光也。未光者，因可疑而未光也。故上六引兑亦曰未光，本卦独初爻无比，无比则无所疑矣，故曰行未疑也。行者与人和说也，变坎为狐疑，疑之象也。</p><p>九二，孚兑，吉，悔亡。</p><p>本卦无应与，专以阴阳相比言。刚中为孚，居阴为悔，盖来兑在前，私系相近，因居阴不正，所以不免悔也。</p><p>九二当兑之时，承比阴柔，说之当有悔矣。然刚中之德，孚信内充，虽见小人，自守不失正，所谓和而不同也。占者能如是，以孚而说，则吉而悔亡矣。</p><h3 id="《象》曰-孚兑之吉-信志也。" tabindex="-1">《象》曰：孚兑之吉，信志也。 <a class="header-anchor" href="#《象》曰-孚兑之吉-信志也。" aria-label="Permalink to “《象》曰：孚兑之吉，信志也。”">​</a></h3><p>心之所存为志，信志，即诚心二字。二刚实居中，诚信出于刚中之志，岂又说小人而自失。革九四辞同义异，革则人信，孚则己信。</p><p>六三，来兑凶。</p><p>自内至外为往，自外至内为来。凶者非惟不足以得人之与，且有以取人之恶，所以凶也。何也?盖初刚正，二刚中，乃君子也，说之不以道，岂能说哉?求亲而反疏矣。如弘霸尝元忠之粪，彭孙濯李宪之足，丁谓拂莱公之须，皆为人所贱，而至今犹有遗羞，岂不凶。</p><p>三阴柔，不中正，上无应与，近比于初与二之阳，乃来求而悦之，是自卑以求悦于人，不知有礼义者矣，故其占凶。</p><h3 id="《象》曰-来兑之凶-位不当也。" tabindex="-1">《象》曰：来兑之凶，位不当也。 <a class="header-anchor" href="#《象》曰-来兑之凶-位不当也。" aria-label="Permalink to “《象》曰：来兑之凶，位不当也。”">​</a></h3><p>阴柔不中正。</p><p>九四，商兑未宁，介疾有喜。</p><p>商者商度也，中爻巽，巽为不果，商之象也。宁者安宁也。两间谓之介，分限也。故人守节，亦谓之介。四与三，上下异体，犹疆介然，故以介言之。比乎五者公也理也，故不敢舍公而从私，比乎三者私也情也，故不能割情而就理，此其所以商度未宁也。商者四，介者九。</p><p>四承九五之中正，而下比六三之柔邪，故有商度未宁之象。然质本阳刚，若能介然守正，疾恶柔邪，而相悦乎同体之五，如此则有喜矣，故戒占者如此。</p><h3 id="《象》曰-九四之喜-有庆也。" tabindex="-1">《象》曰：九四之喜，有庆也。 <a class="header-anchor" href="#《象》曰-九四之喜-有庆也。" aria-label="Permalink to “《象》曰：九四之喜，有庆也。”">​</a></h3><p>与君相悦则得，得其柔刚之正道，而有福庆矣。</p><p>九五，孚于剥，有厉。</p><p>剥谓阴能剥阳，指上六也。剥即剥卦消阳之名，兑之九五正当剥之六五，故言剥。以人事论，如明皇之李林甫，德宗之卢杞，皆以阴柔容悦，剥乎阳者也。孚者，凭国家之承平，恃一己之聪明，以小人不足畏而孚信之，则内而蛊惑其心志，外而壅蔽其政令，国事日为之紊乱矣，所以有厉。因悦体人易孚之，所以设此有厉之戒。不然九五中正，安得有厉。</p><p>九五阳刚中正，当悦之时，而居尊位，密近上六，上六阴柔，为悦之主，处悦之极，乃妄悦以剥阳者也。故戒占者，若信上六，则有危矣。</p><h3 id="《象》曰-孚于剥-位正当也。" tabindex="-1">《象》曰：孚于剥，位正当也。 <a class="header-anchor" href="#《象》曰-孚于剥-位正当也。" aria-label="Permalink to “《象》曰：孚于剥，位正当也。”">​</a></h3><p>与履九五同。</p><p>上六，引兑。</p><p>引者开弓也，心志专一之意，与萃引吉之引同，中爻离错坎，坎为弓，故用引字。萃六二变坎，故亦用引字，本卦二阴，三曰来兑，止来于下，其字犹缓，其为害浅，至上六则悦之极矣，故引兑，开弓发矢，其情甚急，其为害深，故九五有厉。</p><p>上六阴柔居悦之极，为悦之主，专于悦五之*阳者也，故有引兑之象。不言吉凶者，五已有危厉之戒矣。</p><ul><li>“专于悦五之”原文阙，据慈恩本补上。</li></ul><h3 id="《象》曰-上六引兑-未光也。" tabindex="-1">《象》曰：上六引兑，未光也。 <a class="header-anchor" href="#《象》曰-上六引兑-未光也。" aria-label="Permalink to “《象》曰：上六引兑，未光也。”">​</a></h3><p>未光者，私而不公也。盖悦至于极，则所悦者必暗昧之事，不光明矣。故萃卦上体乃悦，亦曰未光。</p>',39)])])}const f=e(l,[["render",h]]);export{_ as __pageData,f as default};
